function getParisMins(){const d=new Date(new Date().toLocaleString("en-US",{timeZone:"Europe/Paris"}));return{dow:d.getDay(),mins:d.getHours()*60+d.getMinutes()};}
function isOpen(inst){const{dow,mins}=getParisMins();if(!(inst.days||[]).includes(dow))return{open:false,session:"closed"};const o=inst.openH[0]*60+inst.openH[1],c=inst.closeH[0]*60+inst.closeH[1];const inReg=c<o?(mins>=o||mins<c):(mins>=o&&mins<c);if(inReg)return{open:true,session:"regular"};if(inst.preH){const po=inst.preH[0]*60+inst.preH[1],pc=inst.preClose[0]*60+inst.preClose[1];if(mins>=po&&mins<pc)return{open:true,session:"extended"};}return{open:false,session:"closed"};}
function priceKey(inst){return`${inst.sym}_${inst.type}_${inst.cur}`;}
function getLive(prices,inst){const p=prices[priceKey(inst)];return p&&p.price>0?p.price:REF[inst.sym]||0;}
function fmtP(p,cur){if(!p)return"—";if(p>=10000)return p.toLocaleString("fr-FR",{maximumFractionDigits:0})+" "+cur;if(p>=100)return p.toLocaleString("fr-FR",{maximumFractionDigits:2})+" "+cur;if(p>=1)return p.toLocaleString("fr-FR",{maximumFractionDigits:4})+" "+cur;return p.toLocaleString("fr-FR",{maximumFractionDigits:6})+" "+cur;}

/* ══════════════════════════════════════════════════
   IBKR HOOK
══════════════════════════════════════════════════ */
function useIBKR(){
  const[s,setS]=useState({
    status:"connecting", account:null, nav:0, cash:0,
    buying_power:0, unrealized_pnl:0, positions:[], orders:[],
    prices:{}, risk:null, social:{feed:[],sentiment:{}},
    performance:null, autoStatus:null,
    instrumentInfo:{total:0, available:0, margin_ok:0, margin_nok:0},
  });
  const[autoLogs, setAutoLogs]=useState([]);
  const ws=useRef(null), timer=useRef(null), retries=useRef(0);

  const addLog=(entry)=>setAutoLogs(prev=>[...prev.slice(-199), entry]);

  const apply=useCallback((m)=>{
    // Handle auto_log messages immediately
    if(m.type==="auto_log"){
      addLog(m.entry);
      return;
    }
    setS(prev=>{
      const n={...prev};
      if(m.nav!==undefined)       n.nav=m.nav;
      if(m.cash!==undefined)      n.cash=m.cash;
      if(m.buying_power!==undefined) n.buying_power=m.buying_power;
      if(m.unrealized_pnl!==undefined) n.unrealized_pnl=m.unrealized_pnl;
      if(m.account)  n.account=m.account;
      if(m.risk)     n.risk=m.risk;
      if(m.positions)n.positions=m.positions;
      if(m.orders)   n.orders=m.orders;
      if(m.type==="price_update"&&m.key&&m.data)
        n.prices={...n.prices,[m.key]:m.data};
      if(m.type==="status")
        n.status=m.connected?"live":"disconnected";
      if(m.type==="snapshot"){
        n.status=m.connected?"live":"disconnected";
        if(m.positions)n.positions=m.positions;
        if(m.orders)   n.orders=m.orders;
        if(m.prices)   n.prices={...n.prices,...m.prices};
      }
      if(m.type==="order_update"&&m.order)
        n.orders=[...n.orders.filter(o=>o.order_id!==m.order.order_id),m.order];
      if(m.type==="auto_status")
        n.autoStatus=m;
      if(m.type==="performance")
        n.performance=m;
      if(m.type==="social_update")
        n.social={feed:m.tweets||[],sentiment:m.sentiment||{}};
      return n;
    });
  },[]);

  useEffect(()=>{
    const connect=()=>{
      if(ws.current?.readyState<=1) return;
      setS(p=>({...p,status:"connecting"}));
      const sock=new WebSocket("ws://localhost:8000/ws");
      ws.current=sock;
      sock.onopen=()=>{
        retries.current=0;
        addLog({ts:new Date().toLocaleTimeString("fr-FR"),
                msg:"🔌 WebSocket connecté à NINABOT backend",level:"info"});
      };
      sock.onmessage=e=>{try{apply(JSON.parse(e.data));}catch{}};
      sock.onerror=()=>{};
      sock.onclose=()=>{
        setS(p=>({...p,status:"disconnected"}));
        timer.current=setTimeout(connect,
          Math.min(1000*Math.pow(2,retries.current++),15000));
      };
    };
    connect();
    const ping=setInterval(()=>{
      if(ws.current?.readyState===WebSocket.OPEN)
        ws.current.send(JSON.stringify({action:"ping"}));
    },20000);
    // Fetch performance + instrument info every 30s
    const perfInterval=setInterval(()=>{
      fetch("http://localhost:8000/performance").then(r=>r.json())
        .then(d=>setS(p=>({...p,performance:d}))).catch(()=>{});
      fetch("http://localhost:8000/instruments").then(r=>r.json())
        .then(d=>setS(p=>({...p,instrumentInfo:d}))).catch(()=>{});
    },30000);
    // Poll auto-status every 5s
    const autoInterval=setInterval(()=>{
      fetch("http://localhost:8000/auto/status").then(r=>r.json())
        .then(d=>{
          setS(p=>({...p,autoStatus:d}));
          if(d.logs) d.logs.forEach(l=>addLog(l));
        }).catch(()=>{});
    },5000);
    return()=>{
      clearInterval(ping);
      clearInterval(perfInterval);
      clearInterval(autoInterval);
      clearTimeout(timer.current);
      ws.current?.close();
    };
  },[apply]);

  // ── API functions ────────────────────────────────────
  const subscribePrice=useCallback((inst)=>{
    if(ws.current?.readyState===WebSocket.OPEN)
      ws.current.send(JSON.stringify({action:"subscribe_price",symbol:inst.sym,
        sec_type:inst.type,exchange:inst.exch,currency:inst.cur,
        primary_exch:inst.primaryExch||""}));
  },[]);

  const placeOrder=useCallback(async(params)=>{
    try{
      const r=await fetch("http://localhost:8000/order",{method:"POST",
        headers:{"Content-Type":"application/json"},body:JSON.stringify(params)});
      const j=await r.json();
      return r.ok?j:{ok:false,error:j.detail||"Erreur"};
    }catch(e){return{ok:false,error:String(e)};}
  },[]);

  const cancelOrder=useCallback(async(id)=>{
    await fetch(`http://localhost:8000/order/${id}`,{method:"DELETE"});
  },[]);

  const cancelAllOrders=useCallback(()=>{
    fetch("http://localhost:8000/orders/all",{method:"DELETE"}).catch(()=>{});
  },[]);

  const closePosition=useCallback((symbol,secType="STK",exchange="SMART",currency="USD",qty=0)=>{
    const btn_id=`close_${symbol}`;
    fetch("http://localhost:8000/position/close",{
      method:"POST",headers:{"Content-Type":"application/json"},
      body:JSON.stringify({symbol,sec_type:secType,exchange,currency,qty}),
    }).catch(()=>{});
  },[]);

  const closeAllPositions=useCallback(()=>{
    fetch("http://localhost:8000/positions/close_all",{method:"POST"}).catch(()=>{});
  },[]);

  const startAutoTrader=useCallback((mode,cfg,instruments,indicators)=>{
    return fetch("http://localhost:8000/auto/start",{
      method:"POST",headers:{"Content-Type":"application/json"},
      body:JSON.stringify({mode,cfg,instruments,active_indicators:indicators,active:true}),
    }).then(r=>r.json());
  },[]);

  const stopAutoTrader=useCallback(()=>{
    fetch("http://localhost:8000/auto/stop",{method:"POST"}).catch(()=>{});
  },[]);

  const triggerScan=useCallback(()=>{
    addLog({ts:new Date().toLocaleTimeString("fr-FR"),
            msg:"⚡ Scan manuel déclenché...",level:"info"});
    fetch("http://localhost:8000/scan/trigger",{method:"POST"})
      .then(r=>r.json())
      .then(d=>addLog({ts:new Date().toLocaleTimeString("fr-FR"),
                       msg:`Scan terminé: ${d.signals||0} signal(s) · ${JSON.stringify(d.results?.slice(0,3)||[])}`,level:"info"}))
      .catch(e=>addLog({ts:new Date().toLocaleTimeString("fr-FR"),msg:`Scan error: ${e}`,level:"error"}));
  },[]);

  const warmupPrices=useCallback(()=>{
    addLog({ts:new Date().toLocaleTimeString("fr-FR"),
            msg:"📡 Warm-up Yahoo Finance en cours...",level:"info"});
    fetch("http://localhost:8000/warmup",{method:"POST"})
      .then(r=>r.json())
      .then(d=>addLog({ts:new Date().toLocaleTimeString("fr-FR"),
                       msg:`✅ Warm-up: ${d.prices_loaded||0} prix chargés · Exemples: ${JSON.stringify(d.sample||{})}`,
                       level:"info"}))
      .catch(e=>addLog({ts:new Date().toLocaleTimeString("fr-FR"),msg:`Warmup error: ${e}`,level:"error"}));
  },[]);

  const kill=useCallback(()=>{
    fetch("http://localhost:8000/risk/kill",{method:"POST"}).catch(()=>{});
  },[]);

  return{
    ...s, autoLogs, setAutoLogs, addLog,
    kill, subscribePrice, placeOrder, cancelOrder,
    cancelAllOrders, closePosition, closeAllPositions,
    startAutoTrader, stopAutoTrader, triggerScan, warmupPrices,
  };
}


