/* ══════════════════════════════════════════════════
   LOG PANEL — Affichage logs temps réel
══════════════════════════════════════════════════ */
function LogPanel({ ibkr, maxLines=200, title="LOGS SYSTÈME", filter="" }) {
  const logs = (ibkr?.autoLogs || []).slice(-maxLines).filter(l=>!filter||l.msg.includes(filter));
  const endRef = useRef(null);

  useEffect(()=>{
    endRef.current?.scrollIntoView({behavior:"smooth"});
  },[logs.length]);

  const lvlCol = (lvl) => lvl==="error"?C.neonR:lvl==="warn"?C.neonA:C.neonG;
  const lvlBg  = (lvl) => lvl==="error"?"rgba(255,51,102,0.08)":lvl==="warn"?"rgba(255,149,0,0.06)":"transparent";

  return <div style={{background:C.deep,border:`1px solid ${C.glassBorder}`,borderRadius:10,overflow:"hidden",display:"flex",flexDirection:"column",minHeight:180}}>
    <div style={{padding:"7px 12px",background:C.surf,borderBottom:`1px solid ${C.glassBorder}`,display:"flex",justifyContent:"space-between",alignItems:"center",flexShrink:0}}>
      <div style={{display:"flex",alignItems:"center",gap:8}}>
        <div style={{width:6,height:6,borderRadius:"50%",background:logs.length>0?C.neonG:C.dim,animation:logs.length>0?"glowPulse 1.5s infinite":"none"}}/>
        <span style={{fontSize:8,fontWeight:700,letterSpacing:2,color:C.neon,fontFamily:"'IBM Plex Mono',monospace"}}>{title}</span>
        <span style={{fontSize:7,padding:"1px 6px",borderRadius:99,background:`${C.neon}15`,color:C.neon,fontFamily:"'IBM Plex Mono',monospace"}}>{logs.length}</span>
      </div>
      <div style={{display:"flex",gap:4}}>
        <button onClick={()=>ibkr?.warmupPrices&&ibkr.warmupPrices()} style={{fontSize:7,padding:"2px 8px",borderRadius:4,background:`${C.neonA}15`,border:`1px solid ${C.neonA}30`,color:C.neonA,cursor:"pointer",fontFamily:"'IBM Plex Mono',monospace",fontWeight:700}}>📡 PRIX YF</button>
        <button onClick={()=>ibkr?.triggerScan&&ibkr.triggerScan()} style={{fontSize:7,padding:"2px 8px",borderRadius:4,background:`${C.neonG}15`,border:`1px solid ${C.neonG}30`,color:C.neonG,cursor:"pointer",fontFamily:"'IBM Plex Mono',monospace",fontWeight:700}}>⚡ SCAN</button>
        <button onClick={()=>ibkr?.setAutoLogs&&ibkr.setAutoLogs([])} style={{fontSize:7,padding:"2px 8px",borderRadius:4,background:`${C.neonR}15`,border:`1px solid ${C.neonR}25`,color:C.neonR,cursor:"pointer",fontFamily:"'IBM Plex Mono',monospace"}}>CLEAR</button>
      </div>
    </div>
    <div style={{flex:1,overflow:"auto",maxHeight:260,padding:"6px 10px",fontFamily:"'IBM Plex Mono',monospace"}}>
      {logs.length===0&&(
        <div style={{color:C.dim,fontSize:9,padding:"16px 0",textAlign:"center",lineHeight:2}}>
          En attente de logs...<br/>
          <span style={{fontSize:8}}>Activez un mode de trading pour voir les scans en direct</span>
        </div>
      )}
      {logs.map((l,i)=>(
        <div key={i} style={{display:"flex",gap:8,marginBottom:1,fontSize:9,lineHeight:1.6,background:lvlBg(l.level),borderRadius:3,padding:"0 4px"}}>
          <span style={{color:C.dim,flexShrink:0,fontSize:8}}>{l.ts}</span>
          <span style={{color:lvlCol(l.level),wordBreak:"break-all"}}>{l.msg}</span>
        </div>
      ))}
      <div ref={endRef}/>
    </div>
  </div>;
}

function CloseView({ ibkr }) {
  const pos = ibkr.positions || [];
  const orders = (ibkr.orders||[]).filter(o=>o.status!=="Filled"&&o.status!=="Cancelled");
  const info = ibkr.instrumentInfo || {};

  return <div style={{display:"flex",flexDirection:"column",gap:12}}>
    {/* INFO BULLE — Instruments + Marge */}
    <div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:10}}>
      {[
        ["Total instruments", info.total||0, C.neon],
        ["Disponibles (prix)", info.available||0, C.neonG],
        ["Marge OK", info.margin_ok||0, C.neonG],
        ["Marge insuffisante", info.margin_nok||0, C.neonR],
      ].map(([l,v,col])=>(
        <div key={l} style={{background:`${col}08`,border:`1px solid ${col}25`,borderRadius:12,padding:"14px",textAlign:"center"}}>
          <div style={{fontFamily:"'Syne',sans-serif",fontSize:26,fontWeight:900,color:col,marginBottom:4}}>{v}</div>
          <div style={{fontSize:8,color:C.muted,fontFamily:"'IBM Plex Mono',monospace",letterSpacing:1}}>{l.toUpperCase()}</div>
        </div>
      ))}
    </div>

    {/* FERMETURE RAPIDE POSITIONS */}
    <div style={{background:C.card,border:`1px solid rgba(255,51,102,0.3)`,borderRadius:14,padding:"18px"}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14}}>
        <div style={{fontSize:8,fontWeight:700,letterSpacing:3,color:C.neonR,fontFamily:"'IBM Plex Mono',monospace"}}>
          POSITIONS OUVERTES — FERMETURE RAPIDE ({pos.length})
        </div>
        {pos.length>0&&(
          <button onClick={(e)=>{
              const btn=e.currentTarget;
              if(btn.disabled)return;
              btn.disabled=true;
              btn.textContent="⏳ En cours...";
              fetch("http://localhost:8000/positions/close_all",{method:"POST"})
                .catch(()=>{}).finally(()=>{setTimeout(()=>{btn.disabled=false;btn.textContent="🔴 FERMER TOUT ("+pos.length+")";},5000);});
            }} style={{padding:"8px 18px",borderRadius:8,background:"linear-gradient(135deg,#ff3366,#cc0033)",border:"none",color:"#fff",fontWeight:700,fontSize:10,cursor:"pointer",fontFamily:"'IBM Plex Mono',monospace",letterSpacing:1}}>
            🔴 FERMER TOUT ({pos.length})
          </button>
        )}
      </div>
      {pos.length===0&&(
        <div style={{textAlign:"center",padding:"24px 0",color:C.muted,fontSize:11,fontFamily:"'IBM Plex Mono',monospace"}}>
          AUCUNE POSITION OUVERTE
        </div>
      )}
      {pos.map((p,i)=>{
        const pnlC = (p.pnl||0)>=0?C.neonG:C.neonR;
        return <div key={p.sym} style={{display:"flex",alignItems:"center",gap:12,padding:"12px 14px",borderRadius:10,marginBottom:6,background:`${pnlC}08`,border:`1px solid ${pnlC}20`}}>
          <div style={{flex:1}}>
            <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:4}}>
              <span style={{fontSize:14,fontWeight:800,color:C.text,fontFamily:"'Syne',sans-serif"}}>{p.sym}</span>
              <span style={{fontSize:9,padding:"2px 8px",borderRadius:99,background:(p.qty||0)>0?`${C.neonG}20`:`${C.neonR}20`,color:(p.qty||0)>0?C.neonG:C.neonR,fontFamily:"'IBM Plex Mono',monospace",fontWeight:700}}>{(p.qty||0)>0?"LONG":"SHORT"} ×{Math.abs(p.qty||0)}</span>
              <span style={{fontSize:9,color:C.muted,fontFamily:"'IBM Plex Mono',monospace"}}>Entrée: {(p.avg_cost||0).toFixed(2)}</span>
            </div>
            <div style={{height:3,background:"rgba(255,255,255,0.06)",borderRadius:99,overflow:"hidden"}}>
              <div style={{height:"100%",width:`${Math.min(Math.abs(p.pct||0)*5,100)}%`,background:pnlC,borderRadius:99}}/>
            </div>
          </div>
          <div style={{textAlign:"right",minWidth:90}}>
            <div style={{fontSize:14,fontWeight:800,color:pnlC,fontFamily:"'Syne',sans-serif"}}>{(p.pnl||0)>=0?"+":""}{(p.pnl||0).toFixed(2)} €</div>
            <div style={{fontSize:9,color:pnlC,fontFamily:"'IBM Plex Mono',monospace"}}>{(p.pct||0)>=0?"+":""}{(p.pct||0).toFixed(2)}%</div>
          </div>
          <button onClick={(e)=>{
            const btn=e.currentTarget;
            if(btn.disabled)return;
            btn.disabled=true;
            btn.textContent="...";
            fetch("http://localhost:8000/position/close",{
              method:"POST",headers:{"Content-Type":"application/json"},
              body:JSON.stringify({symbol:p.sym,sec_type:p.sec_type||"STK",exchange:"SMART",currency:p.currency||"USD",qty:Math.abs(p.qty||0)})
            }).catch(()=>{}).finally(()=>{setTimeout(()=>{btn.disabled=false;btn.textContent="✕ FERMER";},3000);});
          }} style={{padding:"8px 14px",borderRadius:8,background:`${C.neonR}15`,border:`1px solid ${C.neonR}40`,color:C.neonR,fontWeight:700,fontSize:9,cursor:"pointer",fontFamily:"'IBM Plex Mono',monospace",letterSpacing:1,whiteSpace:"nowrap"}}>
            ✕ FERMER
          </button>
        </div>;
      })}
    </div>

    {/* ORDRES EN ATTENTE */}
    <div style={{background:C.card,border:`1px solid rgba(255,149,0,0.25)`,borderRadius:14,padding:"18px"}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14}}>
        <div style={{fontSize:8,fontWeight:700,letterSpacing:3,color:C.neonA,fontFamily:"'IBM Plex Mono',monospace"}}>ORDRES EN ATTENTE ({orders.length})</div>
        {orders.length>0&&<button onClick={()=>ibkr.cancelAllOrders&&ibkr.cancelAllOrders()} style={{padding:"7px 14px",borderRadius:7,background:`${C.neonR}15`,border:`1px solid ${C.neonR}30`,color:C.neonR,fontSize:9,cursor:"pointer",fontFamily:"'IBM Plex Mono',monospace",fontWeight:700}}>✕ CANCEL TOUT</button>}
      </div>
      {orders.length===0&&<div style={{textAlign:"center",padding:"14px 0",color:C.muted,fontSize:11,fontFamily:"'IBM Plex Mono',monospace"}}>AUCUN ORDRE EN ATTENTE</div>}
      {orders.map(o=><div key={o.order_id} style={{display:"flex",alignItems:"center",gap:10,padding:"9px 12px",borderRadius:8,marginBottom:5,background:`${C.neonA}08`,border:`1px solid ${C.neonA}18`}}>
        <span style={{fontSize:8,padding:"2px 7px",borderRadius:99,background:o.action==="BUY"?`${C.neonG}20`:`${C.neonR}20`,color:o.action==="BUY"?C.neonG:C.neonR,fontWeight:700,fontFamily:"'IBM Plex Mono',monospace"}}>{o.action}</span>
        <span style={{fontSize:11,fontWeight:700,color:C.text,fontFamily:"'IBM Plex Mono',monospace",flex:1}}>{o.symbol} ×{o.qty} · {o.order_type}</span>
        <span style={{fontSize:9,color:C.neonA,fontFamily:"'IBM Plex Mono',monospace"}}>{o.status}</span>
        <button onClick={()=>ibkr.cancelOrder(o.order_id)} style={{padding:"5px 10px",borderRadius:6,background:`${C.neonR}12`,border:`1px solid ${C.neonR}25`,color:C.neonR,fontSize:8,cursor:"pointer",fontFamily:"'IBM Plex Mono',monospace",fontWeight:700}}>CANCEL</button>
      </div>)}
    </div>
  </div>;
}

/* ══════════════════════════════════════════════════
   FLASH INFO — Variation P&L temps réel
══════════════════════════════════════════════════ */
function FlashInfo({ ibkr }) {
  const perf = ibkr.performance;
  if (!perf) return null;
  const fi = perf.flash_info || {};
  const col = (fi.color === "green") ? C.neonG : C.neonR;
  return (
    <div style={{display:"flex",alignItems:"center",gap:7,padding:"3px 10px",background:`${col}10`,border:`1px solid ${col}22`,borderRadius:99}}>
      <div style={{width:5,height:5,borderRadius:"50%",background:col}}/>
      <span style={{fontSize:8,fontWeight:700,color:col,fontFamily:"'IBM Plex Mono',monospace",letterSpacing:.5}}>
        {fi.label || "P&L"}
      </span>
      {perf.win_rate > 0 && (
        <span style={{fontSize:7,color:C.muted,fontFamily:"'IBM Plex Mono',monospace"}}>WR {perf.win_rate}%</span>
      )}
    </div>
  );
}

