      <div style={{position:"fixed",inset:0,background:`radial-gradient(ellipse at 20% 50%, ${C.neon}06 0%, transparent 50%), radial-gradient(ellipse at 80% 20%, ${C.neonP}04 0%, transparent 40%)`,pointerEvents:"none",zIndex:0}}/>

