// ── Helpers ───────────────────────────────────────
function bubbleColor(score) {
  if (score >= 75) return "#ff3366";
  if (score >= 60) return "#ff9500";
  if (score >= 45) return "#ffdd00";
  return "#00ff88";
}
function bubbleLabel(score) {
  if (score >= 75) return "CRITIQUE";
  if (score >= 60) return "ÉLEVÉ";
  if (score >= 45) return "MODÉRÉ";
  return "FAIBLE";
}
function levelColor(level) {
  return level==="danger"?"#ff3366":level==="warning"?"#ff9500":"#00ff88";
}
function debtRatio(a) {
  return (a.liabilities/a.assets*100).toFixed(0);
}
function capexFCF(a) {
  return (a.capex/a.fcf).toFixed(1);
}

function MiniSparkBD({data,col,w=120,h=32}){
  if(!data||data.length<2) return null;
  const mn=Math.min(...data),mx=Math.max(...data),r=mx-mn||1;
  const pts=data.map((v,i)=>`${(i/(data.length-1))*w},${h-((v-mn)/r)*(h-4)-2}`).join(" ");
  const fill=`M0,${h} ${data.map((v,i)=>`L${(i/(data.length-1))*w},${h-((v-mn)/r)*(h-4)-2}`).join(" ")} L${w},${h} Z`;
  const id=`bds${Math.random().toString(36).slice(2,6)}`;
  return <svg width={w} height={h} style={{display:"block",overflow:"visible"}}>
    <defs><linearGradient id={id} x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor={col} stopOpacity=".3"/><stop offset="100%" stopColor={col} stopOpacity="0"/></linearGradient></defs>
    <path d={fill} fill={`url(#${id})`}/>
    <polyline points={pts} fill="none" stroke={col} strokeWidth="1.5" strokeLinecap="round" style={{filter:`drop-shadow(0 0 4px ${col})`}}/>
    <circle cx={+pts.split(" ").pop().split(",")[0]} cy={+pts.split(" ").pop().split(",")[1]} r="3" fill={col}/>
  </svg>;
}

